action.code:
int num_entries;
infile.read(reinterpret_cast<char*>(&num_entries), sizeof(int));

for (int i = 0; i < num_entries; ++i) {
    unsigned char character;
    infile.read(reinterpret_cast<char*>(&character), sizeof(unsigned char));

    int code_length;
    infile.read(reinterpret_cast<char*>(&code_length), sizeof(int));

    std::string code;
    code.resize(code_length);
    infile.read(&code[0], code_length);

    std::shared_ptr<Node> current = root;
    for (char bit : code) {
        if (bit == '0') {
            if (!current->left) {
                current->left = std::make_shared<Node>('+', 0);
            }
            current = current->left;
        } else if (bit == '1') {
            if (!current->right) {
                current->right = std::make_shared<Node>('+', 0);
            }
            current = current->right;
        }
    }
    current->data = character;
}

